// ─── Utility Functions ─────────────────────────────────────────────────

/** Get game by ID */
export function getGameById(id) {
  return games.find(g => g.id === id)
}

/** Get games by console */
export function getGamesByConsole(consoleName) {
  if (consoleName === 'ALL') return games
  return games.filter(g => g.console === consoleName)
}

/** Get featured games (for homepage) */
export function getFeaturedGames(limit = 8) {
  // Add random noise to each game's score so it shuffles games of similar tier
  const scoredGames = games.map(g => {
    const baseScore = (g.badge === 'featured' ? 100 : g.badge === 'popular' ? 50 : 0) + (g.rating || 0) * 10;
    const randomNoise = Math.random() * 30; // 30 points of randomness to mix up the order
    return { game: g, score: baseScore + randomNoise };
  });

  scoredGames.sort((a, b) => b.score - a.score);
  return scoredGames.slice(0, limit).map(item => item.game);
}

/** Get unique consoles */
export function getConsoles() {
  return ['ALL', ...new Set(games.map(g => g.console))]
}

/** Get all games */
export function getAllGames() {
  return games
}

/** Search games by title */
export function searchGames(query) {
  const q = query.toLowerCase().trim()
  if (!q) return games
  return games.filter(g =>
    g.title.toLowerCase().includes(q) ||
    g.console.toLowerCase().includes(q) ||
    g.genre?.toLowerCase().includes(q) ||
    g.developer?.toLowerCase().includes(q)
  )
}

/** Get game count per console */
export function getConsoleCounts() {
  const counts = {}
  for (const game of games) {
    counts[game.console] = (counts[game.console] || 0) + 1
  }
  return counts
}

/** Get games by genre */
export function getGamesByGenre(genre) {
  return games.filter(g => g.genre?.toLowerCase() === genre.toLowerCase())
}

/** Get unique genres */
export function getGenres() {
  return [...new Set(games.map(g => g.genre).filter(Boolean))]
}

/** Get era from year */
export function getEraFromYear(year) {
  if (!year) return 'Unknown';
  if (year < 1990) return '80s';
  if (year < 2000) return '90s';
  if (year < 2010) return '2000s';
  return '2010s+';
}

/** Get unique eras available */
export function getEras() {
  const eras = games.map(g => getEraFromYear(g.year)).filter(Boolean);
  return [...new Set(eras)].sort();
}


/** Get console era */
export function getConsoleEra(consoleName) {
  const map = {
    'NES': '8-bit',
    'GB': '8-bit',
    'GBC': '8-bit',
    'SNES': '16-bit',
    'GEN': '16-bit',
    'GBA': '32-bit',
    'NDS': '64-bit',
    'N64': '64-bit'
  };
  return map[consoleName] || 'Unknown';
}

export default games
